def fast_polish(tour: List[int], cur_sc: float) -> Tuple[List[int], float]:
    """Fast 2-opt + 1-relocate polish for multi-start seed screening."""
    improved = True
    while improved:
        improved = False
        L = len(tour)
        for i in range(L):
            for j in range(i + 2, L + 1):
                nt = tour[:i] + tour[i:j][::-1] + tour[j:]
                sc, _ = eval_seq(nt)
                if sc > cur_sc + 1e-6:
                    tour, cur_sc, improved = nt, sc, True
                    break
            if improved:
                break
        if improved:
            continue
        for i in range(L):
            x_node = tour[i]
            rem = tour[:i] + tour[i + 1 :]
            for j in range(len(rem) + 1):
                if j == i:
                    continue
                nt = rem[:j] + [x_node] + rem[j:]
                sc, _ = eval_seq(nt)
                if sc > cur_sc + 1e-6:
                    tour, cur_sc, improved = nt, sc, True
                    break
            if improved:
                break
    return tour, cur_sc

