def advance_drive_leg(t: int, batt: float, dt: int, de: float, floor_b: float, limit_t: int) -> Tuple[int, float]:
    """Simulate dt drive ticks spending de energy in chunks of <= 8 ticks, inserting solar waits if needed."""
    if dt <= 0:
        return t, batt
    if t + dt > limit_t:
        return limit_t + 1, -1.0
    rem = dt
    e_rate = de / dt
    while rem > 0:
        step = 8 if rem > 8 else rem
        if t + step > limit_t:
            return limit_t + 1, -1.0
        nb = batt + (sol_cum[t + step] - sol_cum[t]) - e_rate * step
        if nb > 100.0:
            nb = 100.0
        while nb < floor_b:
            # Wait 1 tick before this step to accumulate solar charge
            t += 1
            if t + rem > limit_t:
                return limit_t + 1, -1.0
            batt = min(100.0, batt + sol_net[t])
            nb = batt + (sol_cum[t + step] - sol_cum[t]) - e_rate * step
            if nb > 100.0:
                nb = 100.0
        batt = nb
        t += step
        rem -= step
    return t, batt

def eval_seq(seq: List[int]) -> Tuple[float, int]:
    t = max(3, start_tick - 1)  # first command executes at start_tick = t + 1
    batt = start_batt
    score = 0.0
    first_leg = True
    cur = 0

    for nxt in seq:
        if first_leg:
            dt = start_ticks[nxt]
            de = start_energy[nxt]
            first_leg = False
        else:
            dt = pticks[cur][nxt]
            de = penergy[cur][nxt]

        if dt > 0:
            t, batt = advance_drive_leg(t, batt, dt, de, batt_floor, max_return_tick - 1)
            if batt < 0.0:
                return -1.0, t

        # Sample tick
        t += 1
        if t > max_return_tick:
            return -1.0, t
        while min(100.0, batt + sol_net[t]) - samp_cost < 14.0:
            batt = min(100.0, batt + sol_net[t])
            t += 1
            if t > max_return_tick:
                return -1.0, t
        batt = min(100.0, batt + sol_net[t]) - samp_cost

        dl = dls[nxt]
        if dl is None or t <= dl - 3:
            score += vals[nxt]
        elif t <= dl - 1:
            score += 0.80 * vals[nxt] + 0.20 * lates[nxt]
        elif t == dl:
            score += 0.55 * vals[nxt] + 0.45 * lates[nxt]
        else:
            score += lates[nxt]
        cur = nxt

    # Return to BASE (index 0) with 8-tick chunked battery & solar simulation
    dt_ret = start_ticks[0] if first_leg else pticks[cur][0]
    de_ret = start_energy[0] if first_leg else penergy[cur][0]
