def coord_to_node(self, x: float, y: float) -> int:
    i = min(self.nx - 1, max(0, int(x / self.cell)))
    j = min(self.ny - 1, max(0, int(y / self.cell)))
    u = j * self.nx + i
    if self.reachable[u]:
        return u
    # Snap to nearest Base-connected graph cell
    best_n = u
    best_d = 1e9
    for rad in (4, 12):
        for dj in range(-rad, rad + 1):
            nj = j + dj
            if not (0 <= nj < self.ny):
                continue
            for di in range(-rad, rad + 1):
                ni = i + di
                if not (0 <= ni < self.nx):
                    continue
                cand = nj * self.nx + ni
                if self.reachable[cand]:
                    cx, cy = (ni + 0.5) * self.cell, (nj + 0.5) * self.cell
                    d = math.hypot(cx - x, cy - y)
                    if d < best_d:
                        best_d = d
                        best_n = cand
        if best_d < 1e8:
            return best_n
    return best_n

